import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Star } from 'lucide-react';
import { obtenerSucursalesOrdenadas } from '../data/mockDiscoveryDB';
import '../estilos/escritorio/principal.css';
import '../estilos/movil/responsivo.css';

/**
 * Inicio — V4: Premium grid of bus companies sorted by ranking.
 * Minimalist card design: Logo, Name, Stars. Trust through brand.
 */
const Inicio = () => {
    const [sucursales, setSucursales] = useState([]);

    useEffect(() => {
        // Load sucursales from mock, auto-sorted by ranking (highest first)
        setSucursales(obtenerSucursalesOrdenadas());
    }, []);

    // Render star rating with lucide-react
    const renderEstrellas = (ranking) => {
        const llenas = Math.floor(ranking);
        const tieneMedia = ranking % 1 >= 0.3;
        const vacias = 5 - llenas - (tieneMedia ? 1 : 0);

        return (
            <div style={{ display: 'flex', alignItems: 'center', gap: '2px' }}>
                {Array.from({ length: llenas }, (_, i) => (
                    <Star key={`f${i}`} size={16} fill="#f59e0b" color="#f59e0b" />
                ))}
                {tieneMedia && (
                    <Star key="h" size={16} fill="#f59e0b" color="#f59e0b" style={{ clipPath: 'inset(0 50% 0 0)' }} />
                )}
                {Array.from({ length: vacias }, (_, i) => (
                    <Star key={`e${i}`} size={16} fill="none" color="#475569" />
                ))}
                <span style={{ marginLeft: '6px', fontSize: '0.85rem', color: '#94a3b8', fontWeight: 600 }}>
                    {ranking}
                </span>
            </div>
        );
    };

    return (
        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9', padding: '1.5rem' }}>
            <div style={{ maxWidth: '900px', margin: '0 auto' }}>

                {/* Hero Section */}
                <div style={{ textAlign: 'center', marginBottom: '2rem', paddingTop: '1rem' }}>
                    <h1 style={{ fontSize: '1.8rem', fontWeight: 800, marginBottom: '0.5rem' }}>
                        Terminal de Buses <span style={{ color: '#3b82f6' }}>Bolivia</span>
                    </h1>
                    <p style={{ color: '#64748b', fontSize: '0.95rem', maxWidth: '400px', margin: '0 auto 1.5rem' }}>
                        Selecciona tu empresa de confianza y reserva tu viaje
                    </p>

                    <Link to="/buscar" style={{
                        display: 'inline-flex', alignItems: 'center', gap: '0.5rem',
                        padding: '0.8rem 1.5rem', borderRadius: '10px',
                        background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
                        color: 'white', textDecoration: 'none', fontWeight: 600, fontSize: '0.95rem',
                        boxShadow: '0 4px 14px rgba(59,130,246,0.3)',
                        transition: 'transform 0.2s',
                    }}>
                        🔍 Buscar Todos los Viajes
                    </Link>
                </div>

                {/* Sucursales Grid */}
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))',
                    gap: '1rem',
                }}>
                    {sucursales.map((s, idx) => (
                        <Link
                            key={s.id}
                            to={`/sucursal/${s.id}`}
                            style={{ textDecoration: 'none', color: 'inherit' }}
                        >
                            <div style={{
                                background: '#1e293b',
                                borderRadius: '14px',
                                padding: '1.5rem',
                                border: '1px solid #334155',
                                cursor: 'pointer',
                                transition: 'all 0.25s ease',
                                position: 'relative',
                                overflow: 'hidden',
                            }}
                            onMouseEnter={e => {
                                e.currentTarget.style.borderColor = s.colorLogo;
                                e.currentTarget.style.transform = 'translateY(-2px)';
                                e.currentTarget.style.boxShadow = `0 8px 25px rgba(0,0,0,0.3)`;
                            }}
                            onMouseLeave={e => {
                                e.currentTarget.style.borderColor = '#334155';
                                e.currentTarget.style.transform = 'translateY(0)';
                                e.currentTarget.style.boxShadow = 'none';
                            }}
                            >
                                {/* Ranking badge for top 3 */}
                                {idx < 3 && (
                                    <div style={{
                                        position: 'absolute', top: '0.75rem', right: '0.75rem',
                                        background: idx === 0 ? '#f59e0b' : idx === 1 ? '#94a3b8' : '#cd7f32',
                                        color: '#0f172a', fontSize: '0.7rem', fontWeight: 800,
                                        padding: '0.2rem 0.5rem', borderRadius: '4px',
                                    }}>
                                        #{idx + 1}
                                    </div>
                                )}

                                {/* Logo */}
                                <div style={{
                                    width: '56px', height: '56px', borderRadius: '12px',
                                    background: `${s.colorLogo}20`,
                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    fontSize: '1.8rem', marginBottom: '1rem',
                                    border: `1px solid ${s.colorLogo}40`,
                                }}>
                                    {s.logo}
                                </div>

                                {/* Name */}
                                <h3 style={{
                                    margin: '0 0 0.5rem', fontSize: '1.1rem', fontWeight: 700,
                                    color: '#f1f5f9',
                                }}>
                                    {s.nombre}
                                </h3>

                                {/* Stars */}
                                {renderEstrellas(s.ranking)}

                                {/* Subtle trip count */}
                                <div style={{
                                    marginTop: '0.75rem', fontSize: '0.75rem', color: '#475569',
                                }}>
                                    {s.totalViajes} viajes realizados
                                </div>
                            </div>
                        </Link>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Inicio;
